async function redoShot(id){await requireApi();const p=C.clone(S.projects.drama),shot=p.shots.find(s=>s.id===id);if(!shot)throw Error('镜头不存在');const role=p.roles.find(r=>r.id===shot.role),image=await flatten(role?.src||shot.src);const t=await sendJob({kind:'image',input:{prompt:buildShotPrompt(p,shot,'image'),images:[image],ratio:p.ratio},metadata:metadata(p,'shot',shot.title+' · 单镜头重做',{shot_id:id,ratio:p.ratio})},{shot,ratio:p.ratio,roles:p.roles,revision:p.revision},'shot');render();return t;}
async function redoAsset(asset){await requireApi();const p=[...Object.values(S.projects),...(S.archive||[])].find(p=>p.assets.some(a=>a.id===asset.id));if(!p)throw Error('原项目不存在');const snap=C.clone(asset.snapshot),image=await flatten(snap.sku.src);delete snap.apiImage;await sendJob({kind:'image',input:{prompt:`严格保持参考商品的形状、颜色和标识，制作${C.scenes[snap.scene]}。${p.aiPlan?.visual_prompt||p.brief||''}。不添加文字。`.slice(0,1950),images:[image],ratio:snap.ratio},metadata:metadata(p,'image',asset.title+' · AI重做',{sku_name:snap.sku.name,scene:snap.scene,ratio:snap.ratio})},snap,'image');render();}

async function recordClips(shots,assets,ratio,progress=()=>{}){
 if(!window.MediaRecorder||!HTMLCanvasElement.prototype.captureStream)throw Error('浏览器不支持视频编码，可下载原始AI片段。');
 const prepared=[];
 try{
  for(const shot of shots){const a=findClip(shot,assets);if(!a)throw Error('镜头“'+shot.title+'”尚未选用真实AI视频。请在视频版本中预览并采用片段。');if(a.snapshot.shot.prompt!==shot.prompt||(a.snapshot.shot.motionPrompt||'')!==(shot.motionPrompt||'')||a.ratio!==ratio)throw Error('镜头“'+shot.title+'”已修改，请重新生成或核对采用的视频版本。');const video=document.createElement('video');video.muted=true;video.playsInline=true;video.preload='auto';video.src=a.videoUrl;
   await new Promise((resolve,reject)=>{const timeout=setTimeout(()=>reject(Error('读取AI片段超时，请确认本机缓存存在。')),20000);video.onloadeddata=()=>{clearTimeout(timeout);resolve();};video.onerror=()=>{clearTimeout(timeout);reject(Error('AI片段无法解码，请检查本机缓存。'));};});prepared.push({shot,video,duration:Math.min(Number(shot.duration)||3,Number.isFinite(video.duration)?video.duration:10)});
  }
  const dims=C.ratios[ratio]||C.ratios['16:9'],canvas=document.createElement('canvas');canvas.width=960;canvas.height=Math.round(960*dims[1]/dims[0]);const ctx=canvas.getContext('2d'),w=canvas.width,h=canvas.height;
  const mime=['video/webm;codecs=vp9','video/webm;codecs=vp8','video/mp4'].find(x=>MediaRecorder.isTypeSupported(x));if(!mime)throw Error('浏览器没有可用编码器，请下载原始AI片段。');
  const stream=canvas.captureStream(24),recorder=new MediaRecorder(stream,{mimeType:mime,videoBitsPerSecond:3000000}),chunks=[];const finished=new Promise((resolve,reject)=>{recorder.ondataavailable=e=>{if(e.data.size)chunks.push(e.data);};recorder.onstop=()=>resolve(new Blob(chunks,{type:mime}));recorder.onerror=()=>reject(Error('编排视频编码失败，原始AI片段仍保留。'));});
  let completed=0;const total=prepared.reduce((n,x)=>n+x.duration,0);recorder.start(150);
  try{for(const {shot,video,duration} of prepared){video.currentTime=0;await video.play();const start=performance.now();while(!video.ended&&(performance.now()-start)/1000<duration){ctx.fillStyle='#15231c';ctx.fillRect(0,0,w,h);const scale=Math.max(w/video.videoWidth,h/video.videoHeight),dw=video.videoWidth*scale,dh=video.videoHeight*scale;ctx.drawImage(video,(w-dw)/2,(h-dh)/2,dw,dh);const gradient=ctx.createLinearGradient(0,h*.65,0,h);gradient.addColorStop(0,'#00000000');gradient.addColorStop(1,'#00000099');ctx.fillStyle=gradient;ctx.fillRect(0,0,w,h);ctx.fillStyle='white';ctx.textAlign='center';ctx.font=`500 ${Math.round(w*.025)}px "PingFang SC",sans-serif`;ctx.fillText(shot.subtitle||'',w*.5,h*(shot.subtitleY||.88),w*.9);progress(Math.min(99,Math.round((completed+Math.min(duration,(performance.now()-start)/1000))/total*100)));await new Promise(r=>setTimeout(r,1000/24));}video.pause();completed+=duration;}recorder.stop();const blob=await finished;progress(100);return {blob,extension:mime.includes('mp4')?'mp4':'webm'};}
  finally{if(recorder.state!=='inactive')recorder.stop();stream.getTracks().forEach(t=>t.stop());}
 }finally{prepared.forEach(({video})=>{video.pause();video.removeAttribute('src');video.load();});}
}
// v2.1: explicit frame approval and video-version adoption.
const DEFAULT_DIRECTION='保持角色身份、服饰、场景方位与光线连续。严格按本镜头说明安排动作，不自行增加人物、道具或可读文字。';
const allProjects=()=>[...Object.values(S.projects),...(S.archive||[])];
function frameKey(p,s){const r=p.roles.find(r=>r.id===s.role);return JSON.stringify([s.prompt,s.imagePrompt||'',s.role,r?.desc||'',p.ratio,p.directorNotes||DEFAULT_DIRECTION,s.frameAssetId||s.frameVersion||'reference']);}
function approved(p,s){return !!s.frameApproval&&s.frameApproval.key===frameKey(p,s);}
function findClip(s,assets){return s.activeClipId?assets.find(a=>a.id===s.activeClipId&&a.type==='api-video'&&a.snapshot.shot?.id===s.id):null;}
function migrateClips(){for(const p of allProjects().filter(p=>p.type==='drama'))for(const s of p.shots){if(!s.clipSelectionMigrated){const old=p.assets.filter(a=>a.type==='api-video'&&a.snapshot.shot?.id===s.id).at(-1);if(old)s.activeClipId=old.id;s.clipSelectionMigrated=true;}}}
function checkNoActiveVideo(p,s){if(S.tasks.some(t=>t.remote&&t.projectId===p.id&&t.kind==='video'&&t.snapshot.shot?.id===s.id&&['queued','running','completing'].includes(t.status)))throw Error('此镜头已有视频任务执行中，请先等待结果，避免重复计费。');}
function buildShotPrompt(p,s,kind){const r=p.roles.find(r=>r.id===s.role),notes=p.directorNotes||DEFAULT_DIRECTION;const action=kind==='image'?(s.imagePrompt||s.prompt):(s.motionPrompt||s.prompt);return `${kind==='image'?'以参考图建立本镜头的单一开始画面，保留人物外观，不把先后动作画成重复人物。':'从已确认首帧开始，生成一个连续镜头。人物动作和摄影机运动分开理解，不在镜头内部自行切换场景。'}主要角色：${r?.name||''}，${r?.desc||''}。${kind==='image'?'首帧构图':'动作、运镜及结束状态'}：${action}。全片约束：${notes}。${/倒影|反射|镜面/.test(action)?'核对反射与屋内人物的一一对应和动作同步；反射具有玻璃的透射与明暗关系，不把反射变成额外实体人物。':''}不添加字幕、气泡或可读屏幕文字，字幕由工作台后期叠加。`.slice(0,1950);}
async function sendClip(p,s){if(!approved(p,s))throw Error('请先检查并确认镜头“'+s.title+'”的分镜图。');checkNoActiveVideo(p,s);const shot=C.clone(s),image=await flatten(shot.src);return sendJob({kind:'video',input:{prompt:buildShotPrompt(p,shot,'video'),images:[image],ratio:p.ratio,duration:Number(shot.duration)||3},metadata:metadata(p,'video',`第${shot.episode}集 / ${shot.title} · AI视频`,{shot_id:shot.id,ratio:p.ratio,source_asset_id:shot.frameAssetId||'uploaded-reference'})},{shot,ratio:p.ratio,roles:C.clone(p.roles),revision:p.revision,frameKey:frameKey(p,shot),directorNotes:p.directorNotes||DEFAULT_DIRECTION},'video');}
async function submitDramaV21(includeVideo){const p=S.projects.drama;if(p.generationMode==='local')return localDrama(includeVideo);await requireApi();if(submitting)throw Error('正在提交，请稍候。');if(!p.shots.length)throw Error('请先规划分镜。');const input=C.clone(p);if(includeVideo)for(const s of input.shots){if(!approved(input,s))throw Error('还有未确认或已变更的分镜：'+s.title);checkNoActiveVideo(input,s);}submitting=true;let n=0;try{for(const s of input.shots){if(includeVideo)await sendClip(input,s);else{const r=input.roles.find(r=>r.id===s.role),image=await flatten(s.src||r?.src||'assets/drama.png');await sendJob({kind:'image',input:{prompt:buildShotPrompt(input,s,'image'),images:[image],ratio:input.ratio},metadata:metadata(input,'shot',`第${s.episode}集 / ${s.title} · AI分镜图`,{shot_id:s.id,ratio:input.ratio})},{shot:s,ratio:input.ratio,roles:input.roles,revision:input.revision},'shot');}n++;}return n;}finally{submitting=false;render();}}
function reviewShot(id){const p=S.projects.drama,s=p.shots.find(s=>s.id===id);if(!s)throw Error('镜头不存在。');const frames=p.assets.filter(a=>a.api&&a.type==='shot'&&a.snapshot.shot?.id===id);const warning=/倒影|反射|镜面/.test(s.prompt)?'<div class="notice">此镜头涉及反射：请检查倒影是否对应屋内人物、人物数量和清晰度是否合理。文字约束不能保证模型始终正确。</div>':'';modal(`<h2>检查与确认分镜</h2><p>${E(s.title)} · 确认只保存选择，不调用模型</p>${warning}<img id="frame-review-image" src="${E(s.src)}" alt="待确认分镜" style="width:100%;max-height:34vh;object-fit:contain"><label class="field"><span>候选分镜版本</span><select id="frame-candidate"><option value="current">当前镜头画面${s.frameAssetId?'（已选版本）':' / 参考图'}</option>${frames.map((a,i)=>`<option value="${a.id}">AI分镜 ${i+1} · ${E(a.title)}</option>`).join('')}</select></label>${field('首帧构图说明（用于下次重做图片）',`<textarea id="frame-image-prompt">${E(s.imagePrompt||s.prompt)}</textarea>`)}${field('视频动作与运镜（写清谁移动、如何移动、结束状态）',`<textarea id="frame-motion-prompt">${E(s.motionPrompt||s.prompt)}</textarea>`)}<label class="row tiny" style="margin:15px 0"><input type="checkbox" id="frame-review-confirm">我已检查人物数量、倒影关系、服饰和构图，选择这张图作为视频首帧</label><div class="row wrap"><button class="btn primary" data-api-action="approve-frame" data-shot="${id}">确认分镜（不调用模型）</button><button class="btn" data-api-action="save-shot-notes" data-shot="${id}">仅保存描述</button></div>`);}
async function saveShotNotes(id,approve=false){const p=S.projects.drama,s=p.shots.find(s=>s.id===id);if(!s)throw Error('镜头不存在。');if(approve&&!$('#frame-review-confirm')?.checked)throw Error('请先完成分镜检查并勾选确认。');const motion=$('#frame-motion-prompt').value.trim();if(!motion)throw Error('请填写本镜头的视频动作与运镜。');const candidate=$('#frame-candidate')?.value,a=p.assets.find(a=>a.id===candidate);if(a){s.src=a.src;s.frameAssetId=a.id;s.generated=true;}s.imagePrompt=$('#frame-image-prompt').value.trim().slice(0,1200);s.motionPrompt=$('#frame-motion-prompt').value.trim().slice(0,1200);if(!s.motionPrompt)throw Error('请填写本镜头的视频动作与运镜。');if(approve)s.frameApproval={key:frameKey(p,s),at:Date.now(),assetId:s.frameAssetId||'reference'};else if(s.frameApproval?.key!==frameKey(p,s))delete s.frameApproval;p.revision++;await C.save(true);$('#modal').innerHTML='';render();toast(approve?'分镜已确认，可单独生成视频。':'描述已保存；改变构图后需重新确认。');}
function reviewVideo(id){const p=S.projects.drama,s=p.shots.find(s=>s.id===id);if(!s)throw Error('镜头不存在');if(!approved(p,s)){reviewShot(id);return;}checkNoActiveVideo(p,s);modal(`<h2>仅生成这个镜头的视频</h2><img src="${E(s.src)}" alt="已确认首帧" style="width:100%;max-height:28vh;object-fit:contain"><p><b>${E(s.title)}</b> · ${s.duration}秒 · ${E(p.ratio)}</p><p class="tiny">只提交 1 个视频请求，不重做分镜图。模型按量计费，原视频版本保留；新结果需预览后主动采用。</p>${field('本次视频动作与运镜',`<textarea id="single-motion">${E(s.motionPrompt||s.prompt)}</textarea>`)}<button class="btn primary" data-api-action="submit-single-video" data-shot="${id}">确认生成 1 段视频（可能计费）</button>`);}
async function submitSingleVideo(id){await requireApi();if(submitting)throw Error('正在提交，请稍候。');const p=S.projects.drama,s=p.shots.find(s=>s.id===id);if(!s)throw Error('镜头不存在');const text=$('#single-motion')?.value.trim();if(!text)throw Error('请填写动作与运镜。');s.motionPrompt=text.slice(0,1200);p.revision++;await C.save(true);submitting=true;try{await sendClip(C.clone(p),C.clone(s));$('#modal').innerHTML='';render();toast('已仅提交此镜头的视频，旧结果保留。');}finally{submitting=false;}}
function reviewBatch(){const p=S.projects.drama,missing=p.shots.filter(s=>!approved(p,s));if(missing.length)throw Error('还有 '+missing.length+' 个分镜未确认，请先逐镜检查。');modal(`<h2>生成已确认分镜的视频</h2><p>本次提交 ${p.shots.length} 个视频请求，不重新生成图片。调用按量计费，已有片段保留，新片段完成后需预览并选择采用。</p><button class="btn primary" data-api-action="submit-approved-batch">确认提交 ${p.shots.length} 段视频（可能计费）</button>`);}
function clipVersions(id){const p=S.projects.drama,s=p.shots.find(s=>s.id===id),list=p.assets.filter(a=>a.type==='api-video'&&a.snapshot.shot?.id===id);if(!s)throw Error('镜头不存在');modal(`<h2>视频版本 · ${E(s.title)}</h2><p class="tiny">逐步制作与单镜返修需预览后采用；一键出片可选自动采用或自己选择，旧版本仍保留。</p>${list.length?list.map((a,i)=>`<div style="padding:13px 0;border-bottom:1px solid #ddd"><b>版本 ${i+1}${s.activeClipId===a.id?' · 当前采用':''}</b><video controls preload="metadata" src="${E(a.videoUrl)}" style="width:100%;max-height:28vh"></video><div class="row wrap"><button class="btn small" data-api-action="adopt-clip" data-asset="${a.id}" data-shot="${id}">采用此视频版本</button><button class="btn small" data-api-action="download-clip-asset" data-asset="${a.id}">下载原始片段</button>${nextShot(p,id)?`<button class="btn small" data-api-action="review-tail" data-shot="${E(id)}" data-asset="${E(a.id)}">取尾帧续拍下一镜</button>`:''}</div></div>`).join(''):'<p>还没有真实视频，请先确认分镜并生成。</p>'}`);}
async function adoptClip(id,assetId){const p=S.projects.drama,s=p.shots.find(s=>s.id===id),a=p.assets.find(a=>a.id===assetId&&a.type==='api-video'&&a.snapshot.shot?.id===id);if(!s||!a)throw Error('原镜头或片段不存在。');s.activeClipId=a.id;s.clipSelectionMigrated=true;s.clip=true;s.clipReviewed=true;p.revision++;await C.save(true);$('#modal').innerHTML='';render();toast('已采用此视频版本，其他版本保留。');}
function shotTools(p,s){const frames=frameVersions(p,s);const n=p.assets.filter(a=>a.type==='api-video'&&a.snapshot.shot?.id===s.id).length;return `<p class="tiny">分镜：${approved(p,s)?'已人工确认':s.frameSelection?.key===frameKey(p,s)?'已选分镜':s.frameAutoSelected&&s.frameAutoKey===frameKey(p,s)?'自动选用 · 未人工确认':'待检查或已变更'} · 视频 ${n} 个版本${s.activeClipId?(s.clipReviewed?' · 视频已手动选用':' · 视频已选用，可更换'):''}</p><div class="row wrap"><button class="btn small" data-api-action="frame-versions" data-shot="${s.id}">选择分镜版本 · ${frames.length}</button><button class="btn small" data-api-action="review-frame" data-shot="${s.id}">检查 / 确认分镜</button><button class="btn small" data-api-action="review-video" data-shot="${s.id}">${n?'仅重做视频':'生成此镜视频'}</button>${n?`<button class="btn small" data-api-action="clip-versions" data-shot="${s.id}">视频版本 · ${n}</button>`:''}</div>`;}
document.addEventListener('change',e=>{if(e.target.id==='frame-candidate'){const a=S.projects.drama.assets.find(a=>a.id===e.target.value),s=S.projects.drama.shots.find(s=>s.id===$('[data-api-action="approve-frame"]')?.dataset.shot);$('#frame-review-image').src=a?.src||s?.src;$('#frame-review-confirm').checked=false;}});

async function downloadClipAsset(a){if(!a?.videoUrl)throw Error('片段路径不存在');const r=await fetch(a.videoUrl);if(!r.ok)throw Error('片段文件不可用，请保留配套缓存或演示素材');C.download(await r.blob(),(a.title||'视频片段')+'.mp4');}
async function loadDemo(kind='approved'){const r=await fetch(kind==='continuity'?'assets/continuity-demo.json':'assets/approved-demo.json');if(!r.ok)throw Error('配套演示案例未找到');const d=await r.json();if(d.format!=='forma-demo-v21'||!d.project?.shots?.length)throw Error('案例格式不正确');const old=S.projects.drama;S.archive=S.archive||[];S.archive.push(C.clone(old));const p=C.clone(d.project);p.id=C.uid();p.name=d.project.name+' · 示例';S.projects.drama=p;S.active='drama';S.view='studio';S.step=2;await C.save(true);render();toast('已载入真实API演示样片，不调用模型；原项目已保留在我的项目。');}
// One-click production uses server-side image -> video dependencies. No model quality claim.
const AUTO_BUSY=['submitting','running','blocked','canceling'];
let autoSyncing=false,autoPreviewing=false;
function shortKey(value){const text=JSON.stringify(value);let a=2166136261,b=5381;for(let i=0;i<text.length;i++){a=Math.imul(a^text.charCodeAt(i),16777619);b=Math.imul(b,33)^text.charCodeAt(i);}return text.length+':'+(a>>>0).toString(16)+':'+(b>>>0).toString(16);}
function storyKey(p){return shortKey([p.ratio,p.directorNotes||DEFAULT_DIRECTION,p.roles.map(r=>[r.id,r.name,r.desc,r.src]),p.shots.map(s=>[s.id,s.episode,s.title,s.prompt,s.imagePrompt||'',s.motionPrompt||'',s.role,s.src,s.frameAssetId||'',s.frameVersion||'',s.duration,s.subtitle,s.subtitleY,s.activeClipId||''])]);}
function frameVersions(p,s){return p.assets.filter(a=>a.type==='shot'&&a.snapshot?.shot?.id===s.id);}
function defaultFrameChoice(p,s){const frames=frameVersions(p,s);return frames.some(a=>a.id===s.frameAssetId)?s.frameAssetId:frames.length?frames.at(-1).id:(approved(p,s)||s.frameSelection?.key===frameKey(p,s))?'current':'new';}
function resolveFrameChoice(p,s,choice){if(choice==='new')return null;if(choice==='current')return {id:s.frameAssetId||'uploaded-reference',src:s.src};const a=frameVersions(p,s).find(a=>a.id===choice);if(!a)throw Error('所选分镜版本不存在，请重新选择。');return a;}
function frameVersionsDialog(id){const p=S.projects.drama,s=p.shots.find(s=>s.id===id);if(!s)throw Error('镜头不存在');const frames=frameVersions(p,s);modal(`<h2>选择分镜版本 · ${E(s.title)}</h2><p>当前镜头关联了 ${frames.length} 个生成版本。${frames.length?'逐张比较后选用，选择本身不调用模型。':'下方只有当前参考图，不代表已经生成了多版图片。视频生成和文字分镜表不会出现在此处。'}</p><button class="btn" style="margin-bottom:16px" data-api-action="history-frames" data-shot="${E(id)}">查看历史分镜素材（不调用模型）</button><div class="grid two">${[{id:'current',src:s.src,title:'当前镜头画面 / 参考图'},...frames.map((a,i)=>({...a,title:(a.importedFrom?'历史导入 · ':'')+'分镜版本 '+(i+1)}))].map(a=>`<div><img src="${E(a.src)}" alt="${E(a.title)}" style="width:100%;aspect-ratio:16/9;object-fit:contain;background:#e9ede5"><p><b>${E(a.title)}</b>${a.id===s.frameAssetId?' · 当前选用':''}</p><button class="btn small ${a.id===s.frameAssetId?'':'primary'}" data-api-action="choose-frame-version" data-shot="${E(id)}" data-asset="${E(a.id)}">${a.id===s.frameAssetId?'继续使用这张':'选用这张分镜'}</button></div>`).join('')}</div><p class="tiny">已有视频不会被删除；更换分镜后，需要使用新分镜制作视频，或在视频版本里保留原片段。</p>`);}
async function chooseFrameVersion(id,assetId){const p=S.projects.drama,s=p.shots.find(s=>s.id===id);if(!s)throw Error('镜头不存在');const a=resolveFrameChoice(p,s,assetId);if(!a?.src)throw Error('分镜图片不存在');s.src=a.src;if(assetId!=='current'){s.frameAssetId=a.id;s.generated=true;}delete s.frameApproval;s.frameAutoSelected=false;s.frameSelection={key:frameKey(p,s),at:Date.now(),assetId:s.frameAssetId||'uploaded-reference'};p.revision++;await C.save(true);$('#modal').innerHTML='';render();toast('已选用这张分镜。一键出片会使用它，不重复生成图片。');}
function autoSelections(){const p=S.projects.drama;return Object.fromEntries(p.shots.map((s,i)=>[s.id,$('#auto-frame-'+i)?.value||defaultFrameChoice(p,s)]));}
function updateAutoEstimate(){const p=S.projects.drama,picks=autoSelections(),continuity=$('#auto-continuity')?.value==='continue',n=p.shots.filter((s,i)=>!(continuity&&i>0&&s.episode===p.shots[i-1].episode)&&picks[s.id]==='new').length,el=$('#auto-request-count');const continued=continuity?p.shots.filter((s,i)=>i>0&&s.episode===p.shots[i-1].episode).length:0;if(el)el.textContent=`本次复用 ${p.shots.length-n-continued} 张已选分镜${continued?'，提取 '+continued+' 张上镜尾帧（不调用模型）':''}，新增 ${n} 张图片和 ${p.shots.length} 段视频，共 ${n+p.shots.length} 个模型请求。`;p.shots.forEach((s,i)=>{const connected=continuity&&i>0&&s.episode===p.shots[i-1].episode,select=$('#auto-frame-'+i),note=$('#auto-link-note-'+i);if(select)select.disabled=connected;if(note)note.textContent=connected?'首帧将取自上一镜的视频结尾；此分镜只保留作参考。':'';const im=$('#auto-frame-preview-'+i),a=resolveFrameChoice(p,s,picks[s.id]);if(im){im.src=a?.src||s.src;im.alt=a?'本次选用的分镜':'参考图（将重新生成）';}});}
function reviewAuto(){const p=S.projects.drama;if(!p.shots.length)throw Error('请先规划分镜。');if(AUTO_BUSY.includes(p.autoRun?.status))throw Error('已有一键出片批次，请先等待完成或停止后续。');if(S.tasks.some(t=>t.projectId===p.id&&t.remote&&['queued','running','completing'].includes(t.status)))throw Error('当前项目仍有任务执行中，请先等待或取消，避免重复生成。');modal(`<h2>一键出片 · 使用哪些分镜？</h2><p>优先使用你已选的分镜。每个镜头都可以换版本；“重新生成”只在你选择后执行。文字与参考图将发送百炼，可能产生费用。</p>${field('镜头衔接',`<select id="auto-continuity" aria-label="镜头衔接"><option value="independent">独立镜头：各自使用我选择的分镜</option><option value="continue">同集连续续拍：上一镜尾帧作为下一镜首帧</option></select>`)}<p class="tiny">续拍会串行生成，同集后续镜头使用上一镜实际尾帧，独立分镜保留作参考。跨集重新开始；更换场景请使用独立镜头。参考图服饰应与角色描述一致，否则仍可能换装。续拍需要页面保持打开以读取尾帧和提交后续；关闭后已提交结果保留，恢复页面后续接已确认的批次，提交不明时暂停核查。续拍不是质量保证。</p><div class="grid two">${p.shots.map((s,i)=>{const choice=defaultFrameChoice(p,s),frames=frameVersions(p,s);return `<label class="field"><span>${E(s.title)}</span><img id="auto-frame-preview-${i}" src="${E(resolveFrameChoice(p,s,choice)?.src||s.src)}" alt="本次分镜" style="width:100%;height:110px;object-fit:contain;background:#eef1e9"><select id="auto-frame-${i}" aria-label="${E(s.title)}分镜版本" data-auto-frame="true"><option value="current" ${choice==='current'?'selected':''}>使用当前镜头画面 / 自定义图</option>${frames.map((a,j)=>`<option value="${E(a.id)}" ${choice===a.id?'selected':''}>分镜版本 ${j+1}${s.frameAssetId===a.id?'（当前选用）':''}</option>`).join('')}<option value="new" ${choice==='new'?'selected':''}>重新生成 1 张分镜（可能计费）</option></select><span class="tiny" id="auto-link-note-${i}"></span></label>`;}).join('')}</div>${field('视频完成后',`<select id="auto-adopt-policy" aria-label="视频完成后"><option value="auto">自动采用本批次视频并合成预览</option><option value="manual">保留为候选，我自己选择视频版本</option></select>`)}<p id="auto-request-count" class="notice"></p><p class="tiny">画面和动作可能有误，自动采用不代表质量审核通过。旧版本保留。已提交任务在后台执行；合成预览需要页面打开并位于前台。</p><button class="btn primary" data-api-action="start-auto">开始制作（可能计费）</button>`);updateAutoEstimate();}
async function startAuto(choices=null,options={}){await requireApi();if(submitting)throw Error('正在提交，请稍候。');const p=S.projects.drama;if(!p.shots.length)throw Error('请先规划分镜。');if(AUTO_BUSY.includes(p.autoRun?.status))throw Error('已有一键出片批次，请勿重复提交。');if(S.tasks.some(t=>t.remote&&t.projectId===p.id&&['queued','running','completing'].includes(t.status)))throw Error('当前项目已有执行中的任务。');
 const input=C.clone(p),picks=choices||Object.fromEntries(input.shots.map(s=>[s.id,defaultFrameChoice(input,s)])),run={id:C.uid(),status:'submitting',created:Date.now(),key:storyKey(input),autoAdopt:options.autoAdopt!==false,continuity:!!options.continuity,items:[],previewStatus:'waiting'};
 for(let i=0;i<input.shots.length;i++){const shot=input.shots[i],connected=run.continuity&&i>0&&shot.episode===input.shots[i-1].episode,frame=connected?null:resolveFrameChoice(input,shot,picks[shot.id]||defaultFrameChoice(input,shot));run.items.push({shotId:shot.id,imageId:connected||frame?null:C.uid(),videoId:C.uid(),existingFrame:frame?{id:frame.id,src:frame.src}:null,previousVideoId:connected?run.items[i-1].videoId:null,submitState:'planned',videoPrompt:connected?continuationPrompt(input,shot):null,videoSnapshot:connected?{shot:C.clone(shot),ratio:input.ratio,roles:input.roles,revision:input.revision,autoRunId:run.id}:null});}
 p.autoRunHistory=p.autoRunHistory||[];if(p.autoRun)p.autoRunHistory.push(C.clone(p.autoRun));p.autoRun=run;submitting=true;await C.save(true);$('#modal').innerHTML='';render();
 try{for(let i=0;i<input.shots.length;i++){if(run.status==='canceling'||run.status==='canceled')break;const s=input.shots[i],item=run.items[i];if(item.previousVideoId)continue;const r=input.roles.find(r=>r.id===s.role),image=await flatten(item.existingFrame?.src||s.src||r?.src||'assets/drama.png'),snap={shot:C.clone(s),ratio:input.ratio,roles:input.roles,revision:input.revision,autoRunId:run.id};if(item.existingFrame){snap.shot.src=item.existingFrame.src;snap.shot.frameAssetId=item.existingFrame.id;}
   if(run.status==='canceling'||run.status==='canceled')break;
   if(item.imageId)await sendJob({id:item.imageId,kind:'image',input:{prompt:buildShotPrompt(input,s,'image'),images:[image],ratio:input.ratio},metadata:metadata(input,'shot',`${s.title} · 自动分镜图`,{shot_id:s.id,ratio:input.ratio})},snap,'shot');
   if(run.status==='canceling'||run.status==='canceled')break;
   await sendJob({id:item.videoId,kind:'video',...(item.imageId?{depends_on:item.imageId}:{}),input:{prompt:buildShotPrompt(input,s,'video'),images:item.imageId?[]:[image],ratio:input.ratio,duration:Number(s.duration)||3},metadata:metadata(input,'video',`${s.title} · AI视频`,{shot_id:s.id,ratio:input.ratio,source_asset_id:item.imageId||item.existingFrame.id})},snap,'video');
  }if(run.status==='submitting')run.status='running';
 }catch(e){if(run.status!=='canceled'&&run.status!=='canceling'){run.status='submission_interrupted';run.error=e.message;}throw e;}
 finally{submitting=false;await C.save(true);render();}
 return run;
}
function autoFrame(p,item){return item.existingFrame||autoAsset(p,item.imageId);}
document.addEventListener('change',e=>{if(e.target.dataset?.autoFrame||e.target.id==='auto-continuity')updateAutoEstimate();});

function autoTask(item,key){return S.tasks.find(t=>t.id===item[key]);}
function autoAsset(p,id){if(!id)return null;const t=S.tasks.find(t=>t.id===id);return p.assets.find(a=>a.taskId===id&&a.apiAttempt===t?.apiAttempt);}
async function syncAuto(){if(autoSyncing)return;autoSyncing=true;try{for(const p of allProjects().filter(p=>p.type==='drama')){const run=p.autoRun;if(!run)continue;if(run.status==='ready'&&run.previewStatus==='encoding'&&!autoPreviewing){run.previewStatus='pending';await C.save(true);}if(run.status==='submitting'&&!submitting){run.status='submission_interrupted';run.error='页面在提交期间关闭，已提交任务和结果仍保留。请到任务中心核查，不自动补发请求。';await C.save(true);}
 if(!['running','blocked'].includes(run.status))continue;
 await advanceContinuations(p,run);if(!['running','blocked'].includes(run.status))continue;
 const bad=!!run.continuationError||run.items.some(i=>['imageId','videoId'].some(k=>['failed','unknown','canceled','interrupted'].includes(autoTask(i,k)?.apiStatus)));
 if(bad){if(run.status!=='blocked'){run.status='blocked';run.error=run.continuationError||'部分任务失败、取消或提交结果不明。后续依赖暂停；请在任务中心核查并处理，不会自动重提付费请求。';await C.save(true);}continue;}
 if(run.status==='blocked'){run.status='running';delete run.error;await C.save(true);}
 if(!run.items.every(i=>autoFrame(p,i)&&autoAsset(p,i.videoId)))continue;
 if(run.autoAdopt===false){for(const item of run.items){const frame=autoFrame(p,item),clip=autoAsset(p,item.videoId);clip.src=frame.src;clip.snapshot.shot.src=frame.src;clip.snapshot.shot.frameAssetId=frame.id;}run.status='candidates_ready';run.completed=Date.now();run.previewStatus='manual';await C.save(true);render();toast('视频版本已生成，请选择想采用的片段；当前已选版本保持不变。');continue;}
 if(storyKey(p)!==run.key){run.status='conflict';run.error='生成期间分镜、素材或已选片段有修改。结果已保留在素材区，请核对后逐镜采用；未覆盖当前编辑。';await C.save(true);render();continue;}
 migrateClips();p.shotVersions=p.shotVersions||[];p.shotVersions.push({created:Date.now(),reason:'一键出片前的镜头版本',shots:C.clone(p.shots)});
 for(const item of run.items){const s=p.shots.find(s=>s.id===item.shotId),frame=autoFrame(p,item),clip=autoAsset(p,item.videoId);s.src=frame.src;s.frameAssetId=frame.id;s.generated=true;if(!item.existingFrame)delete s.frameApproval;s.frameAutoSelected=!item.existingFrame;if(item.existingFrame)s.frameSelection={key:frameKey(p,s),at:Date.now(),assetId:frame.id};s.frameAutoKey=frameKey(p,s);s.activeClipId=clip.id;s.clipSelectionMigrated=true;s.clip=true;s.clipReviewed=false;clip.snapshot.shot.src=frame.src;clip.snapshot.shot.frameAssetId=frame.id;clip.snapshot.sourceImageTaskId=item.imageId;}
 run.status='ready';run.completed=Date.now();run.previewStatus='pending';p.revision++;await C.save(true);render();toast('本批次片段已自动采用，正在准备整集预览；可随后逐镜检查。');
 }}finally{autoSyncing=false;}await maybeAutoPreview();}
async function maybeAutoPreview(force=false){const p=S.projects.drama,run=p?.autoRun;if(!run||run.status!=='ready'||autoPreviewing)return;if(!force&&run.previewStatus!=='pending')return;if(!window.FormaUI?.movie||S.view!=='studio'||S.active!=='drama'||document.visibilityState==='hidden'||$('#modal')?.innerHTML)return;
 autoPreviewing=true;run.previewStatus='encoding';await C.save(true);try{await FormaUI.movie(true);run.previewStatus='shown';delete run.previewError;}catch(e){run.previewStatus='failed';run.previewError=e.message;toast('片段已保留，预览合成未完成：'+e.message);}finally{autoPreviewing=false;await C.save(true);render();}}
async function cancelAuto(){const p=S.projects.drama,run=p.autoRun;if(!run||!AUTO_BUSY.includes(run.status))return;run.status='canceling';await C.save(true);const errors=[];for(const item of run.items)for(const key of ['videoId','imageId']){const t=autoTask(item,key);if(!t||['done','failed','unknown','canceled'].includes(t.apiStatus))continue;try{await apiAction(t.id,'cancel');}catch(e){errors.push(e.message);}}run.status=errors.length?'canceling':'canceled';run.error=errors.length?'部分取消请求未完成，请在任务中心核查：'+errors.join('；'):'已停止本地后续与自动采用。已受理的供应商运算和费用不保证撤销。';await C.save(true);render();}
function autoBanner(p){const run=p.autoRun;if(!run)return '';const names={submitting:'正在提交一键出片',running:'自动制作中',blocked:'等待处理异常',ready:'自动初稿已就绪 · 待人工检查',candidates_ready:'视频候选已生成 · 等你选择',conflict:'结果已保留 · 当前编辑有变更',submission_interrupted:'提交未完整结束 · 请核查任务',canceling:'停止后续中',canceled:'已停止后续'};const done=run.items.filter(i=>autoAsset(p,i.videoId)).length;return `<div class="notice auto-run-status"><b>${E(names[run.status]||run.status)}</b><p class="tiny">${done} / ${run.items.length} 段视频已返回${run.previewStatus==='shown'?' · 当前集预览已合成':''}。${E(run.error||run.previewError||'分镜图完成后自动生成视频；全部返回后采用本批次片段并准备成片预览。')}</p>${AUTO_BUSY.includes(run.status)?'<button class="btn small" data-api-action="cancel-auto">停止本批次后续</button>':''}${run.status==='candidates_ready'?'<button class="btn small" data-api-action="goto-production">选择分镜 / 视频版本</button>':''}${run.status==='ready'?'<div class="row wrap"><button class="btn small primary" data-api-action="preview-auto">预览当前集（不调用模型）</button><button class="btn small" data-act="export-all-movies">批量导出全部剧集</button></div>':''}</div>`;}

let pendingClipChoice=null;
function clipMatches(a,s,ratio){return a?.type==='api-video'&&a.snapshot?.shot?.id===s.id&&a.snapshot.shot.prompt===s.prompt&&(a.snapshot.shot.motionPrompt||'')===(s.motionPrompt||'')&&a.ratio===ratio;}
function ensureMovieClips(p,episodes,single){const shots=single?[single]:p.shots.filter(s=>episodes.includes(s.episode)),missing=shots.filter(s=>!clipMatches(findClip(s,p.assets),s,p.ratio));if(!missing.length)return true;const choices=missing.map(s=>({shotId:s.id,asset:p.assets.filter(a=>clipMatches(a,s,p.ratio)).at(-1)}));pendingClipChoice={projectId:p.id,key:storyKey(p),choices:choices.map(c=>({shotId:c.shotId,assetId:c.asset?.id}))};modal(`<h2>还缺 ${missing.length} 个镜头的可用片段</h2><p>当前项目：${E(p.name)} · ${E(location.origin||'本机工作台')}</p>${missing.map((s,i)=>`<p><b>${E(s.title)}</b>：${choices[i].asset?'已有匹配的视频，但还没选用。':'没有与当前描述匹配的视频；分镜图本身还不是视频。'} <button class="btn small" data-api-action="clip-versions" data-shot="${E(s.id)}">自己选择视频版本</button></p>`).join('')}<div class="row wrap">${choices.every(c=>c.asset)?'<button class="btn primary" data-api-action="adopt-available">批量采用已有片段并预览（不调用模型）</button>':''}<button class="btn" data-api-action="goto-production">返回批量制作 / 一键出片</button><button class="btn" data-api-action="load-demo">载入已验证演示案例（不调用模型）</button></div><p class="tiny">载入案例会保留当前项目到“我的项目”。一键出片需要调用模型并可能计费；此窗口不会自动发起生成。</p>`);return false;}
async function adoptAvailable(){const choice=pendingClipChoice,p=S.projects.drama;if(!choice||choice.projectId!==p.id||choice.key!==storyKey(p))throw Error('项目已变更，请重新预览核对。');for(const c of choice.choices){const s=p.shots.find(s=>s.id===c.shotId),a=p.assets.find(a=>a.id===c.assetId);if(!clipMatches(a,s,p.ratio))throw Error('已有片段与当前分镜不匹配。');}for(const c of choice.choices){const s=p.shots.find(s=>s.id===c.shotId);s.activeClipId=c.assetId;s.clipSelectionMigrated=true;s.clip=true;s.clipReviewed=false;}p.revision++;await C.save(true);$('#modal').innerHTML='';render();await FormaUI.movie(true);}

function historicalFrames(){const list=[];for(const job of jobs.values()){if(job.kind!=='image'||job.metadata?.client_kind!=='shot')continue;for(const version of [...(job.history||[]),job]){const file=version.result?.files?.[0];if(file?.mime?.startsWith('image/'))list.push({id:job.id+'-'+version.attempt,jobId:job.id,attempt:version.attempt,file,metadata:job.metadata,created:version.finished||job.finished||job.created});}}return list.sort((a,b)=>(a.created||0)-(b.created||0));}
async function historyFramesDialog(id){const p=S.projects.drama,s=p.shots.find(s=>s.id===id);if(!s)throw Error('镜头不存在');const data=await request('/api/jobs');data.jobs.forEach(j=>jobs.set(j.id,j));const list=historicalFrames();modal(`<h2>历史分镜素材 · ${E(s.title)}</h2><p>共有 ${list.length} 张已缓存图片。它们可能来自其他项目或旧镜头，并不是当前镜头生成的新版本。请自行核对内容，再导入选用；不调用模型。</p><div class="grid two">${list.map(a=>`<div><img src="${E(a.file.url)}" alt="${E(a.metadata.title)}" style="width:100%;aspect-ratio:16/9;object-fit:contain;background:#eef1e9"><p><b>${E(a.metadata.title)}</b><br><span class="tiny">来自：${E(a.metadata.project_name||'历史项目')} · ${a.metadata.project_id===p.id&&a.metadata.shot_id===s.id?'当前镜头的生成记录':'其他项目 / 旧镜头'} · 尝试 ${a.attempt+1}</span></p><button class="btn small" data-api-action="import-history-frame" data-shot="${E(id)}" data-source="${E(a.id)}">导入并选用这张图片</button></div>`).join('')||'<p>没有已完成的图片生成记录。视频结果与文字分镜表不会计作图片版本。</p>'}</div>`);}
async function importHistoryFrame(shotId,sourceId){const p=S.projects.drama,s=p.shots.find(s=>s.id===shotId),source=historicalFrames().find(a=>a.id===sourceId);if(!s||!source)throw Error('镜头或历史图片不存在');let asset=p.assets.find(a=>a.importedFrom?.id===source.id&&a.snapshot?.shot?.id===shotId);if(!asset){const src=await imageAsData(source.file.url);asset={id:C.uid(),type:'shot',src,title:'历史图片 · '+source.metadata.title,ratio:source.metadata.ratio||p.ratio,created:Date.now(),api:true,importedFrom:{id:source.id,projectId:source.metadata.project_id,shotId:source.metadata.shot_id,title:source.metadata.title},snapshot:{shot:C.clone(s),ratio:source.metadata.ratio||p.ratio,historyImport:true}};p.assets.push(asset);}await chooseFrameVersion(shotId,asset.id);}
async function recoverKnownFrames(){let changed=false;for(const source of historicalFrames()){const p=allProjects().find(p=>p.id===source.metadata.project_id),s=p?.shots?.find(s=>s.id===source.metadata.shot_id);if(!p||!s||p.assets.some(a=>a.id===source.id||a.taskId===source.jobId&&a.apiAttempt===source.attempt))continue;const task=S.tasks.find(t=>t.id===source.jobId),shot=task?.snapshot?.shot?.id===s.id?C.clone(task.snapshot.shot):C.clone(s),src=await imageAsData(source.file.url);p.assets.push({id:source.id,type:'shot',src,title:source.metadata.title,ratio:source.metadata.ratio||p.ratio,created:source.created,taskId:source.jobId,apiAttempt:source.attempt,api:true,recovered:true,snapshot:{shot,ratio:source.metadata.ratio||p.ratio,recoveredFromMetadata:!task?.snapshot?.shot}});changed=true;}if(changed)await C.save(true);return changed;}

async function captureVideoEnd(url,limit){const target=new URL(url,location.href);if(target.origin!==location.origin)throw Error('只可读取本机缓存片段');const video=document.createElement('video');video.muted=true;video.playsInline=true;video.preload='auto';video.src=target.href;try{await new Promise((ok,no)=>{const timer=setTimeout(()=>no(Error('读取续镜源视频超时')),20000);video.onloadeddata=()=>{clearTimeout(timer);ok();};video.onerror=()=>{clearTimeout(timer);no(Error('续镜源视频无法读取'));};});if(!Number.isFinite(video.duration)||video.duration<=0)throw Error('视频时长不可读，请先下载并检查原片段');const end=Math.min(video.duration,Number(limit)||video.duration),time=Math.max(0,end-1/30);if(time>.001)await new Promise((ok,no)=>{const timer=setTimeout(()=>no(Error('读取尾帧超时')),15000);video.onseeked=()=>{clearTimeout(timer);ok();};video.onerror=()=>{clearTimeout(timer);no(Error('尾帧解码失败'));};video.currentTime=time;});const canvas=document.createElement('canvas');canvas.width=video.videoWidth;canvas.height=video.videoHeight;canvas.getContext('2d').drawImage(video,0,0);return {src:canvas.toDataURL('image/jpeg',.94),time,width:canvas.width,height:canvas.height};}finally{video.pause();video.removeAttribute('src');video.load();}}
function nextShot(p,id){const i=p.shots.findIndex(s=>s.id===id),next=p.shots[i+1];return next?.episode===p.shots[i]?.episode?next:null;}
let pendingTail=null;
async function reviewTail(id,assetId){const p=S.projects.drama,s=p.shots.find(s=>s.id===id),next=nextShot(p,id),clip=p.assets.find(a=>a.id===assetId&&a.type==='api-video'&&a.snapshot?.shot?.id===id);if(!s||!next||!clip)throw Error('请先在同一集内添加下一镜头');const key=storyKey(p),tail=await captureVideoEnd(clip.videoUrl,s.duration);pendingTail={projectId:p.id,key,nextId:next.id,clipId:clip.id,...tail};modal(`<h2>用此片段尾帧续拍下一镜</h2><img src="${E(tail.src)}" alt="上镜结束画面" style="width:100%;max-height:40vh;object-fit:contain"><p>来源：${E(s.title)} · ${tail.time.toFixed(2)}秒；用于：${E(next.title)}。保存首帧不调用模型；之后生成视频仍可能计费。</p><p class="tiny">尾帧里的服饰、姿态、人物和错误都会被延续。请先检查画面；换场景或明确切镜时应使用独立分镜。</p><button class="btn primary" data-api-action="apply-tail">选为下一镜首帧（不调用模型）</button>`);}
async function applyTail(){const p=S.projects.drama,t=pendingTail,s=p.shots.find(s=>s.id===t?.nextId);if(!t||!s||t.projectId!==p.id||t.key!==storyKey(p))throw Error('项目已变更，请重新选取尾帧');const a={id:C.uid(),type:'shot',src:t.src,title:'续镜首帧 · '+s.title,ratio:p.ratio,created:Date.now(),snapshot:{shot:C.clone(s),ratio:p.ratio},derivedFrom:{videoId:t.clipId,time:t.time}};p.assets.push(a);await chooseFrameVersion(s.id,a.id);}
function continuationPrompt(input,s){return `从参考画面的结束状态接着拍摄同一连续镜头。保持图中人物实际身份、服装、姿态、站位、场景及光线，不回到最初姿态，不重新换装，不突然变焦或切换场景。只执行接下来的动作：${s.motionPrompt||s.prompt}。全片约束：${input.directorNotes||DEFAULT_DIRECTION}。动作自然连贯，背景人物按剧情自然反应；不凭空新增人物或独立倒影。不添加字幕、可读文字或口播。`.slice(0,1950);}
async function advanceContinuations(p,run){if(!run.items.some(i=>i.previousVideoId)||run.continuationError)return;for(const item of run.items){if(!item.previousVideoId||autoTask(item,'videoId'))continue;if(run.status==='canceled'||run.status==='canceling')return;if(item.submitState==='submitting'){run.continuationError='页面在续镜提交阶段中断，请先核查任务中心，未自动补发请求。';await C.save(true);return;}const previous=autoAsset(p,item.previousVideoId);if(!previous)continue;try{item.submitState='preparing';await C.save(true);const tail=await window.FormaAPI.captureVideoEnd(previous.videoUrl,previous.snapshot.shot.duration);if(!['running','blocked'].includes(run.status))return;const snapshot=C.clone(item.videoSnapshot),frame={id:C.uid(),type:'shot',src:tail.src,title:'自动提取续镜首帧 · '+snapshot.shot.title,ratio:snapshot.ratio,created:Date.now(),snapshot:{shot:C.clone(snapshot.shot),ratio:snapshot.ratio},derivedFrom:{videoId:previous.id,time:tail.time,runId:run.id}};p.assets.push(frame);item.existingFrame={id:frame.id,src:frame.src};snapshot.shot.src=frame.src;snapshot.shot.frameAssetId=frame.id;snapshot.continuedFrom={videoId:previous.id,time:tail.time};item.submitState='submitting';await C.save(true);await sendJob({id:item.videoId,kind:'video',input:{prompt:item.videoPrompt,images:[tail.src],ratio:snapshot.ratio,duration:Number(snapshot.shot.duration)||3},metadata:{...metadata(p,'video',snapshot.shot.title+' · 连续续镜',{shot_id:snapshot.shot.id,ratio:snapshot.ratio,source_asset_id:frame.id}),revision:snapshot.revision}},snapshot,'video');item.submitState='queued';await C.save(true);}catch(e){item.submitState='blocked';run.continuationError='续镜已暂停：'+e.message+'。不会自动重新提交；请先核查原任务。';await C.save(true);return;}}}

window.FormaAPI={captureVideoEnd,reviewTail,applyTail,advanceContinuations,historicalFrames,historyFramesDialog,importHistoryFrame,recoverKnownFrames,frameVersionsDialog,chooseFrameVersion,defaultFrameChoice,resolveFrameChoice,ensureMovieClips,adoptAvailable,reviewAuto,startAuto,syncAuto,cancelAuto,storyKey,autoBanner,downloadClipAsset,loadDemo,reviewShot,reviewVideo,reviewBatch,approved,frameKey,buildShotPrompt,adoptClip,clipVersions,sendClip,migrateClips,recordClips,redoShot,redoAsset,panel,decorate,refreshStatus,request,preview,submitText,downloadResult,status:()=>status,labels};
